:root {
  --paper: #f6efe3;
  --paper-deep: #efe4d0;
  --ink: #4a3c2c;
  --ink-soft: #8a7a63;
  --accent: #c2703d;
  --accent-deep: #a85a2c;
  --sage: #6f9279;
  --sage-deep: #557a62;
  --line: #e0d2b8;
  --gold: #d9a441;
  --danger: #c0563f;
  --card: #fffdf8;
  --shadow: 0 10px 30px rgba(94, 70, 40, 0.12);
  --radius: 16px;
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  min-height: 100%;
}

body {
  color: var(--ink);
  background:
    radial-gradient(1200px 500px at 80% -10%, rgba(217, 164, 65, 0.12), transparent),
    radial-gradient(900px 400px at -10% 10%, rgba(111, 146, 121, 0.12), transparent),
    var(--paper);
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  border-radius: 999px;
  padding: 9px 20px;
  font-size: 14px;
  transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.15s ease;
}
button:active {
  transform: translateY(1px);
}
button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.btn-primary {
  background: linear-gradient(135deg, var(--accent), var(--accent-deep));
  color: #fff;
  box-shadow: 0 4px 14px rgba(194, 112, 61, 0.32);
}
.btn-primary:hover:not(:disabled) {
  box-shadow: 0 6px 18px rgba(194, 112, 61, 0.42);
}
.btn-sage {
  background: linear-gradient(135deg, var(--sage), var(--sage-deep));
  color: #fff;
  box-shadow: 0 4px 14px rgba(85, 122, 98, 0.3);
}
.btn-ghost {
  background: transparent;
  color: var(--accent-deep);
  border: 1.5px solid var(--accent);
}
.btn-ghost:hover:not(:disabled) {
  background: rgba(194, 112, 61, 0.08);
}
.btn-subtle {
  background: var(--paper-deep);
  color: var(--ink);
}

input,
textarea,
select {
  font-family: inherit;
  width: 100%;
  border: 1.5px solid var(--line);
  border-radius: 12px;
  padding: 11px 14px;
  font-size: 14px;
  color: var(--ink);
  background: #fffdf8;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
input:focus,
textarea:focus,
select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(194, 112, 61, 0.14);
}
textarea {
  resize: vertical;
  min-height: 84px;
  line-height: 1.7;
}

.label {
  display: block;
  font-size: 13px;
  color: var(--ink-soft);
  margin: 14px 0 6px;
  font-weight: 600;
}

.coin {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-weight: 700;
  color: #9a6b1e;
}
.coin::before {
  content: "◉";
  color: var(--gold);
  font-size: 15px;
}

.badge {
