$ErrorActionPreference = "Stop"
$base = "http://127.0.0.1:8091/api"
function J($o) { $o | ConvertTo-Json -Compress }
function Post($path, $token, $obj) {
  $h = @{ "Content-Type" = "application/json" }
  if ($token) { $h.Authorization = "Bearer $token" }
  return Invoke-RestMethod -Method Post -Uri "$base$path" -Headers $h -Body (J $obj)
}

Write-Output "=== 1. 注册 A、B（应各得 100） ==="
$a = Post "/auth/register" $null @{ username="testa$(Get-Random)"; password="123456"; nickname="测试甲" }
$b = Post "/auth/register" $null @{ username="testb$(Get-Random)"; password="123456"; nickname="测试乙" }
$ta=$a.token; $tb=$b.token
"A: balance=$($a.user.balance) frozen=$($a.user.frozen)"
"B: balance=$($b.user.balance) frozen=$($b.user.frozen)"

Write-Output "=== 2. A 发布求看悬赏 30（应冻结：A 70/30） ==="
$s = Post "/stories" $ta @{ title="测试-老校门"; city="测试城"; location="测试路1号"; memory="测试回忆内容"; oldPhotos=@("/uploads/seed-old-school.svg"); wish="拍校门"; reward=30 }
"A: balance=$($s.balance) frozen=$($s.frozen)  story.reward=$($s.story.reward) status=$($s.story.status)"
$sid = $s.story.id

Write-Output "=== 3. 余额不足发布（悬赏 999 应失败且余额不变） ==="
try { Post "/stories" $ta @{ title="超额"; memory="x"; oldPhotos=@("/uploads/x.svg"); reward=999 } } catch {
  $resp = $_.ErrorDetails.Message
  "预期失败: $resp"
}

Write-Output "=== 4. A 追加悬赏 10（应：A 60/40，总悬赏 40） ==="
$ap = Post "/stories/$sid/reward" $ta @{ amount=10 }
"A: balance=$($ap.balance) frozen=$($ap.frozen) story.reward=$($ap.story.reward)"

Write-Output "=== 5. A 不能替自己拍（应失败）；B 替拍（成功） ==="
try { Post "/stories/$sid/responses" $ta @{ message="我自己拍"; newPhotos=@("/uploads/seed-new-1.svg") } } catch { "预期失败(自己): $($_.ErrorDetails.Message)" }
$r = Post "/stories/$sid/responses" $tb @{ message="这是 B 看到的现场，校门还在。"; newPhotos=@("/uploads/seed-new-2.svg") }
"B 回应成功，回应数=$($r.story.responses.Count)"
$rid = $r.story.responses[0].id

Write-Output "=== 6. B 重复回应（应失败） ==="
try { Post "/stories/$sid/responses" $tb @{ message="再拍一次"; newPhotos=@("/uploads/seed-new-3.svg") } } catch { "预期失败(重复): $($_.ErrorDetails.Message)" }

Write-Output "=== 7. B 不能确认（应失败）；A 确认结算（应：A frozen=0，B 得 40→140） ==="
try { Post "/stories/$sid/responses/$rid/accept" $tb @{} } catch { "预期失败(权限): $($_.ErrorDetails.Message)" }
$ac = Post "/stories/$sid/responses/$rid/accept" $ta @{}
"A(发起人): balance=$($ac.balance) frozen=$($ac.frozen)  helperGot=$($ac.helperGot) status=$($ac.story.status)"
$bme = Invoke-RestMethod "$base/me" -Headers @{ Authorization="Bearer $tb" }
"B(代看人): balance=$($bme.user.balance) frozen=$($bme.user.frozen)"

Write-Output "=== 8. 重复结算（应失败） ==="
try { Post "/stories/$sid/responses/$rid/accept" $ta @{} } catch { "预期失败(重复结算): $($_.ErrorDetails.Message)" }

Write-Output "=== 9. A 的硬币流水 ==="
$al = Invoke-RestMethod "$base/me/ledgers" -Headers @{ Authorization="Bearer $ta" }
$al.ledgers | ForEach-Object { "  [$($_.typeText)] change=$($_.change) 余额=$($_.balanceAfter) 冻结=$($_.frozenAfter) $($_.remark)" }
Write-Output "=== B 的硬币流水（应有一笔 +40 收入） ==="
$bl = Invoke-RestMethod "$base/me/ledgers" -Headers @{ Authorization="Bearer $tb" }
$bl.ledgers | ForEach-Object { "  [$($_.typeText)] change=$($_.change) 余额=$($_.balanceAfter) 冻结=$($_.frozenAfter)" }

