  plugins: [vue()],
  server: {
    port: 5183,
    proxy: {
      '/api': {
        target: 'http://127.0.0.1:8091',
        changeOrigin: true
      },
      '/uploads': {
        target: 'http://127.0.0.1:8091',
        changeOrigin: true
      }
    }
  }
})

